class Solution {
public:
    string reversePrefix(string s, int k) {
        string res;
        res.reserve(s.size());
        for (int i = k - 1; i >= 0; --i) res += s[i];
        for (int i = k; i < (int)s.size(); ++i) res += s[i];
        return res;
    }
};

